import std.concurrent as conc

pub type AppError = Failed(String)

pub fn main() -> Result<(), AppError> {
    let ch: conc.Channel<Int64> = conc.channel(4)
    let s = ch.trySend(1)
    let a = match s {
        conc.Sent => 1
        conc.Full => 2
        conc.Closed => 3
    }
    let r = ch.tryReceive()
    let b = match r {
        conc.Received(v) => v
        conc.Empty => 0
        conc.Closed => 0
    }
    let _ = a
    let _ = b
    return Ok(())
}

